def remote_arch() -> str:
    """Architecture name used by the release tarballs."""
    m = platform.machine()
    if WINDOWS:
        # The OS's, not this Python's: x64 Python runs emulated on ARM64
        import ctypes
        proc, native = ctypes.c_ushort(), ctypes.c_ushort()
        k32 = ctypes.windll.kernel32
        if k32.IsWow64Process2(k32.GetCurrentProcess(), ctypes.byref(proc),
                               ctypes.byref(native)):
            m = {0xAA64: "arm64", 0x8664: "x86_64"}.get(native.value, m)
        # There is no native arm64 build: clang miscompiles struct varargs
        # (chunk_t) on Windows arm64, see neko-strongswan's
        # build-windows.sh. The x86_64 one runs emulated, Wintun included.
        if m == "arm64":
            m = "x86_64"
    return {"aarch64": "arm64", "amd64": "x86_64",
            "AMD64": "x86_64", "ARM64": "arm64"}.get(m, m)


def fetch(url: str, dest: str) -> str:
    """Download url (or copy a local path) to dest, returns its sha256."""
    h = hashlib.sha256()
    if re.match(r"https?://", url):
        req = urllib.request.Request(url, headers={"User-Agent": "nekoims"})
        src = urllib.request.urlopen(req, timeout=60)
    else:
        src = open(url, "rb")
    with src, open(dest, "wb") as f:
        while chunk := src.read(1 << 16):
            h.update(chunk)
            f.write(chunk)
    return h.hexdigest()


def published_sha256(url: str) -> str | None:
    """The <url>.sha256 sidecar the release workflow uploads, if any."""
    if not re.match(r"https?://", url):
        path = url + ".sha256"
        if not os.path.exists(path):
            return None
        with open(path) as f:
            return f.read().split()[0].lower()
    req = urllib.request.Request(url + ".sha256",
                                 headers={"User-Agent": "nekoims"})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.read().decode().split()[0].lower()
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise


def extract(archive: str, dest: str):
    if zipfile.is_zipfile(archive):
        with zipfile.ZipFile(archive) as z:
            root = os.path.realpath(dest)
            for name in z.namelist():
                target = os.path.realpath(os.path.join(dest, name))
                if os.path.commonpath([root, target]) != root:
                    sys.exit(f"--remote: refusing archive member {name!r}")
            z.extractall(dest)
        return
    with tarfile.open(archive, "r:gz") as tar:
        if hasattr(tarfile, "data_filter"):
            tar.extractall(dest, filter="data")
            return
        root = os.path.realpath(dest)
        for m in tar.getmembers():
            target = os.path.realpath(os.path.join(dest, m.name))
            if (os.path.commonpath([root, target]) != root or
                    m.issym() or m.islnk() or m.isdev()):
                sys.exit(f"--remote: refusing archive member {m.name!r}")
        tar.extractall(dest)


def use_remote(url: str, pinned: str | None) -> str:
    """Download and unpack a static strongSwan build (see the neko-strongswan
    release workflow) into a private directory that is removed on exit.
    Returns the charon path; its vici Python client is put on sys.path."""
    url = url.replace("{arch}", remote_arch())
    work = tempfile.mkdtemp(prefix="strongswan-", dir=RUN_DIR)
    atexit.register(shutil.rmtree, work, ignore_errors=True)

    archive = os.path.join(work, "strongswan.zip" if WINDOWS
                           else "strongswan.tar.gz")
    log(f"fetching {url}")
    try:
        digest = fetch(url, archive)
        expected = pinned or published_sha256(url)
    except (OSError, urllib.error.URLError) as e:
        sys.exit(f"--remote: {e}")
    if expected:
        if digest != expected.lower():
            sys.exit(f"--remote: sha256 mismatch, got {digest}, "
                     f"expected {expected}")
        log(f"sha256 {digest} verified")
    else:
        log(f"warning: no sha256 to verify {url} against (got {digest}), "
            f"pin it with --remote-sha256")

    root = os.path.join(work, "root")
    try:
        extract(archive, root)
    except (tarfile.TarError, OSError) as e:
        sys.exit(f"--remote: bad archive: {e}")
    os.unlink(archive)
    binary = "bin/charon-svc.exe" if WINDOWS else "libexec/ipsec/charon"
    found = glob.glob(os.path.join(root, binary)) + \
        glob.glob(os.path.join(root, "*", binary))
    if len(found) != 1:
        sys.exit(f"--remote: archive has no (unique) {binary}")
    charon = found[0]
    pkg = os.path.dirname(os.path.dirname(charon))
    if not WINDOWS:
        pkg = os.path.dirname(pkg)
    python = os.path.join(pkg, "lib", "python")
    if os.path.isdir(os.path.join(python, "vici")):
        sys.path.insert(0, python)
    return charon


# -- vici --------------------------------------------------------------------

def load_cas(session, paths: list[str] | None) -> int:
    """Trust anchors for the ePDG certificate, loaded over vici: the PEM
    bundles in paths, or the system's trusted roots (Windows). Ones charon
    can't parse (e.g. ECDSA roots on a build without an EC plugin) are
    skipped rather than failing the whole dial."""
    from vici.exception import CommandException
    ders = []
    if paths is None:
        import ssl
        ders = ssl.create_default_context().get_ca_certs(binary_form=True)
    for path in paths or []:
        with open(path) as f:
            pem = f.read()
        ders += [base64.b64decode(b64) for b64 in
                 re.findall(r"-----BEGIN CERTIFICATE-----(.*?)"
                            r"-----END CERTIFICATE-----", pem, re.S)]
    n = skipped = 0
    for der in ders:
        try:
            session.load_cert({"type": "x509", "flag": "CA", "data": der})
            n += 1
        except CommandException:
            skipped += 1
    if skipped:
        log(f"skipped {skipped} CA certificates charon could not parse")
    return n


def epdg_addrs(epdg: str, family: str) -> list[str]:
    """The ePDG host, or its addresses of one family (e.g. IPv4 only from a
    container whose IPv6 default route is the tunnel itself)."""
    if family == "any":
        return [epdg]
    af = socket.AF_INET if family == "4" else socket.AF_INET6
    try:
        infos = socket.getaddrinfo(epdg, 500, af, socket.SOCK_DGRAM)
    except socket.gaierror as e:
        sys.exit(f"cannot resolve {epdg} to IPv{family}: {e}")
    return list(dict.fromkeys(i[4][0] for i in infos))


def connection(epdg: str, identity: str, remote_id: str, remote_auth: str,
               bundle: dict, encap: bool = True,
               family: str = "any") -> dict:
    return {CONN: {
        "version": "2",
        # Always carry ESP in UDP 4500, like phones do. Without a NAT (e.g.
        # IPv6) charon would send raw ESP (IP protocol 50), which home
        # routers' firewalls commonly drop: IKE comes up but no data flows.
        "encap": "yes" if encap else "no",
        "remote_addrs": epdg_addrs(epdg, family),
        # Request INTERNAL_IP4/6_ADDRESS; with the p-cscf plugin loaded
        # charon also asks for P_CSCF_IP4/6_ADDRESS.
        "vips": ["0.0.0.0", "::"],
        "proposals": bundle.get("ike_proposals", IKE_PROPOSALS),
        "keyingtries": "1",
        "dpd_delay": "120s",
        "local": {"auth": "eap-aka", "id": identity},
        # IDr carries the APN (TS 24.302 7.2.2), but the ePDG identifies as
        # one of its nodes, so don't require a match (id_check is from our
        # fork). The ePDG is authenticated by its certificate, or with "eap"
        # (RFC 5998 EAP-only, e.g. Verizon) by the EAP-AKA MSK.
        "remote": {"auth": "eap-aka" if remote_auth == "eap" else "pubkey",
                   "id": remote_id, "id_check": "no"},
        "children": {CHILD: {
            "remote_ts": ["0.0.0.0/0", "::/0"],
            "esp_proposals": bundle.get("esp_proposals", ESP_PROPOSALS),
            # the XFRM interface's; kernel-libipsec (Windows) ignores it
            "if_id_in": hex(IF_ID),
            "if_id_out": hex(IF_ID),
            "start_action": "none",
            "dpd_action": "clear",
            "close_action": "none",
        }},
    }}


P_CSCF_RE = re.compile(r"received P-CSCF server IP (\S+)")
# The ePDG authenticated itself with the EAP MSK (RFC 5998) while we wanted
# a certificate.
EAP_ONLY_RE = re.compile(r"constraint requires public key authentication, "
                         r"but EAP was used")


def initiate(session, logs: list[str] | None = None) -> list[str]:
    """Bring the tunnel up; returns the P-CSCFs charon logged on the way.
    The log lines go to logs too, for a look after a failure."""
    pcscfs = []
    for msg in session.initiate({"child": CHILD, "ike": CONN,
                                 "timeout": "30000", "loglevel": "1"}):
        line = s(msg.get("msg", b""))
        if logs is not None:
            logs.append(line)
        m = P_CSCF_RE.search(line)
        if m and m.group(1) not in pcscfs:
            pcscfs.append(m.group(1))
    return pcscfs


def local_vips(session) -> list[str]:
    for sa in session.list_sas({"ike": CONN}):
        if CONN in sa:
            return [s(v) for v in sa[CONN].get("local-vips", [])]
    return []


def wait_down(events):
    """Block until our IKE SA goes away. On Windows in a thread: Ctrl-C
    (and --lifeline) can't interrupt a blocking recv() there."""
    def listen():
        for kind, msg in events.listen(["ike-updown"]):
            if CONN in msg and s(msg.get("up", b"no")) != "yes":
                return

    if not WINDOWS:
        listen()
        return
    done, err = threading.Event(), []

    def run():
        try:
            listen()
        except Exception as e:  # vici connection lost
            err.append(e)
        finally:
            done.set()
    threading.Thread(target=run, daemon=True).start()
    while not done.wait(0.5):
        pass
    if err:
        raise err[0]


def is_admin() -> bool:
    if WINDOWS:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    return os.geteuid() == 0


def write_state(path: str, state: dict | None):
    if state is None:
        if os.path.exists(path):
            os.unlink(path)
        return
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(state, f, indent=2)
    os.replace(tmp, path)


def tunnel_family_first(pcscfs: list[str], vips: list[str]) -> list[str]:
    """P-CSCFs in an address family the tunnel has go first (stable order
    otherwise). Some ePDGs hand out IPv4 and IPv6 P-CSCFs on a tunnel that
    only has one family (Freedom: IPv6-only, IPv4 ones listed first), and
    nekoims takes the first line of the pcscf file. Bundle flag
    "pcscf_match_family"."""
    fams = {":" in v for v in vips}
    ordered = sorted(pcscfs, key=lambda p: (":" in p) not in fams)
    if ordered and (":" in ordered[0]) not in fams:
        log(f"warning: no P-CSCF matches the tunnel's address family "
            f"({' '.join(vips)}): {' '.join(pcscfs)}")
    return ordered


def write_pcscf(path: str, pcscfs: list[str] | None):
    """One P-CSCF per line, read by nekoims when no -p/"pcscf" is given.
    Removed while there is no tunnel (or no P-CSCF) so it is never stale."""
    if not pcscfs:
        if os.path.exists(path):
            os.unlink(path)
        return
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write("".join(p + "\n" for p in pcscfs))
    os.replace(tmp, path)


# -- main --------------------------------------------------------------------

def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--simcard", default=SIMCARD_DEFAULT,
                    help="simcard-server: unix:/path (or a bare path) or "
                         f"http://host:port (default: {SIMCARD_DEFAULT})")
    ap.add_argument("--bundles", default=BUNDLES_DEFAULT)
    ap.add_argument("--epdg", default=None, help="ePDG host (default: "
                    "carrier bundle, else 3GPP discovery name)")
    ap.add_argument("--mnc-len", type=int, choices=(2, 3), default=None,
                    help="MNC digits in the IMSI (default: 3 for NANP, else 2)")
    ap.add_argument("--apn", default=None, help="APN (default: bundle or ims)")
    ap.add_argument("--remote-id", default=None,
                    help="IDr to send (default: the APN)")
    ap.add_argument("--no-encap", action="store_true",
                    help="send raw ESP when there is no NAT instead of "
                         "always encapsulating it in UDP 4500 (not on "
                         "Windows)")
    ap.add_argument("--remote-auth", choices=("pubkey", "eap"), default=None,
                    help="how the ePDG authenticates (default: bundle "
                         "epdg_auth, else pubkey with a fallback to eap if "
                         "the ePDG turns out to be EAP-only)")
    ap.add_argument("--ca", action="append", default=None,
                    help=f"CA bundle(s) for the ePDG certificate "
                         f"(default: {CA_BUNDLE_DEFAULT or 'the system store'})")
    ap.add_argument("--aka-backend", choices=sorted(AKA_BACKENDS),
                    default="http")
    ap.add_argument("--netns", default="" if WINDOWS else "ims",
                    help='netns for the tunnel interface, "" to keep it in '
                         "the current one (e.g. in a container); Linux only")
    ap.add_argument("--epdg-family", choices=("any", "4", "6"),
                    default="any",
                    help="reach the ePDG over this IP version only")
    ap.add_argument("--ifname", default="NekoIMS" if WINDOWS else "ims0",
                    help="tunnel interface (Windows: the Wintun adapter)")
    ap.add_argument("--mtu", type=int, default=1400)
    ap.add_argument("--charon", default=None, help="charon binary")
    ap.add_argument("--remote", default=None, metavar="URL",
                    help="run the static strongSwan build from this tar.gz "
                         "(.zip on Windows; URL or path, {arch} expands to "
                         "x86_64/arm64) instead of an installed charon")
    ap.add_argument("--remote-sha256", default=None, metavar="HEX",
                    help="expected sha256 of the --remote tarball (default: "
                         "the published <URL>.sha256, if any)")
    ap.add_argument("--plugin-dir", default=None,
                    help="charon plugin directory (default: guessed)")
    ap.add_argument("--loglevel", type=int, default=1,
                    help="charon log level (-1..4)")
    ap.add_argument("--retry", type=int, default=10,
                    help="seconds between redials, 0 to exit on failure")
    ap.add_argument("--log", default=None, metavar="PATH",
                    help="append our and charon's output here")
    ap.add_argument("--lifeline", action="store_true",
                    help="hang up and exit when stdin closes (for a parent "
                         "process that can't signal us, e.g. start.ps1)")
    args = ap.parse_args()

    log_file = None
    if args.log:
        log_file = open(args.log, "a", buffering=1)
        sys.stdout = sys.stderr = log_file
    if args.lifeline:
        import _thread

        def lifeline():
            # EOF once the parent is gone. os.read, not the buffered
            # sys.stdin, whose lock would hang interpreter shutdown.
            while os.read(sys.stdin.fileno(), 4096):
                pass
            log("stdin closed, hanging up")
            _thread.interrupt_main()
        threading.Thread(target=lifeline, daemon=True).start()

    if not is_admin():
        sys.exit("must run as Administrator" if WINDOWS else
                 "must run as root")
    if WINDOWS and args.netns:
        sys.exit("--netns: there are no network namespaces on Windows")
    if WINDOWS and args.no_encap:
        sys.exit("--no-encap: kernel-libipsec on Windows has no raw ESP")
    if args.remote and args.charon:
        sys.exit("--remote and --charon are mutually exclusive")
    if args.remote:
        os.makedirs(RUN_DIR, mode=0o750, exist_ok=True)
        args.charon = use_remote(args.remote, args.remote_sha256)
    elif args.charon:
        # An unpacked release (bin/charon-svc.exe, libexec/ipsec/charon)
        # brings its vici client in lib/python
        d = os.path.dirname(os.path.abspath(args.charon))
        for _ in range(3):
            d = os.path.dirname(d)
            if os.path.isdir(os.path.join(d, "lib", "python", "vici")):
                sys.path.insert(0, os.path.join(d, "lib", "python"))
                break
    try:
        import vici  # noqa: F401
    except ImportError:
        sys.exit("python vici module missing (strongSwan's "
                 "src/libcharon/plugins/vici/python)")

    sim = SimClient(args.simcard)
    try:
        imsi = sim.imsi()
    except (OSError, RuntimeError, KeyError, ValueError) as e:
        sys.exit(f"cannot get the IMSI from the SIM server on {args.simcard}: "
                 f"{e}")
    mcc = imsi[:3]
    mnc_len = args.mnc_len or (3 if mcc in NANP_MCCS else 2)
    mnc = imsi[3:3 + mnc_len]
    bundle = find_bundle(imsi, args.bundles)
    epdg = args.epdg or bundle.get("epdg") or \
        f"epdg.epc.mnc{mnc.zfill(3)}.mcc{mcc}.pub.3gppnetwork.org"
    apn = args.apn or bundle.get("apn", "ims")
    identity = nai(imsi, mcc, mnc)
    log(f"IMSI {imsi}, identity {identity}, ePDG {epdg}, APN {apn}")

    os.makedirs(RUN_DIR, mode=0o750, exist_ok=True)
    conf = os.path.join(RUN_DIR, "strongswan.conf")
    vici_socket = os.path.join(RUN_DIR, "charon.vici")
    state_path = os.path.join(RUN_DIR, "epdg.json")
    pcscf_path = os.path.join(RUN_DIR, "pcscf")

    charon_bin = find_charon(args.charon)
    plugin_dir = find_plugin_dir(charon_bin, args.plugin_dir)
    aka = AKA_BACKENDS[args.aka_backend](sim)
    plugins = BASE_PLUGINS + aka.plugins
    if not plugin_dir:
        log("no plugin directory, assuming a monolithic charon")
    has_p_cscf = not plugin_dir or os.path.exists(
        os.path.join(plugin_dir, "libstrongswan-p-cscf.so"))
    if has_p_cscf:
        plugins.append("p-cscf")
    else:
        log("warning: charon has no p-cscf plugin, the P-CSCF won't be "
            "requested; pass it to nekoims with -p")
    for p in aka.plugins if plugin_dir else []:
        if not os.path.exists(
                os.path.join(plugin_dir, f"libstrongswan-{p}.so")):
            sys.exit(f"--aka-backend {args.aka_backend} needs the {p} plugin, "
                     f"missing from {plugin_dir}")

    with open(conf, "w") as f:
        f.write(strongswan_conf(vici_socket, plugins, aka, args.loglevel,
                                args.ifname))

    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
    if WINDOWS:
        signal.signal(signal.SIGBREAK, lambda *_: sys.exit(0))
        tunnel = WintunTunnel(args.ifname, args.mtu)
    else:
        tunnel = Tunnel(args.netns, args.ifname, args.mtu)
    charon = Charon(charon_bin, conf, vici_socket, log_file)
    try:
        aka.start()
        tunnel.create()
        charon.start()
        if WINDOWS:
            tunnel.setup()

        cmd = charon.session()
        remote_auth = args.remote_auth or bundle.get("epdg_auth")
        # Nobody said how the ePDG authenticates: want a certificate, but
        # fall back to EAP-only if that is what it does (e.g. AT&T).
        auth_guessed = remote_auth is None
        remote_auth = remote_auth or "pubkey"
        if remote_auth == "pubkey":
            n = load_cas(cmd, args.ca or ([CA_BUNDLE_DEFAULT]
                                          if CA_BUNDLE_DEFAULT else None))
            log(f"loaded {n} CA certificates")

        def load_conn():
            cmd.load_conn(connection(epdg, identity, args.remote_id or apn,
                                     remote_auth, bundle,
                                     encap=not args.no_encap,
                                     family=args.epdg_family))
        load_conn()

        events = charon.session()
        while True:
            logs = []
            try:
                pcscfs = initiate(cmd, logs)
            except Exception as e:  # vici.exception.CommandException
                log(f"initiate failed: {e}")
                charon.check()
                if auth_guessed and remote_auth == "pubkey" and \
                        any(EAP_ONLY_RE.search(line) for line in logs):
                    log("the ePDG authenticates with EAP only (RFC 5998), "
                        "redialing that way; set \"epdg_auth\": \"eap\" in "
                        "its carrier bundle (or pass --remote-auth eap)")
                    remote_auth = "eap"
                    load_conn()
                    continue
                if not args.retry:
                    sys.exit(1)
                time.sleep(args.retry)
                continue

            vips = local_vips(cmd)
            if bundle.get("pcscf_match_family", False):
                pcscfs = tunnel_family_first(pcscfs, vips)
            if WINDOWS:
                tunnel.configure(vips, pcscfs)
            else:
                tunnel.configure(vips)
            write_state(state_path, {"netns": args.netns,
                                     "ifname": args.ifname,
                                     "vips": vips, "pcscf": pcscfs,
                                     "epdg": epdg, "imsi": imsi})
            write_pcscf(pcscf_path, pcscfs)
            log(f"tunnel up: {args.netns or '-'}/{args.ifname} "
                f"{' '.join(vips)}")
            for p in pcscfs:
                print(f"PCSCF={p}", flush=True)

            # Block until the IKE SA goes away, then redial.
            try:
                wait_down(events)
            except Exception:  # vici connection lost
                charon.check()
                raise
            log("tunnel down")
            tunnel.unconfigure()
            write_state(state_path, None)
            write_pcscf(pcscf_path, None)
            if not args.retry:
                sys.exit(1)
            time.sleep(args.retry)
    except KeyboardInterrupt:
        pass
    finally:
        try:
            for _ in charon.session().terminate({"ike": CONN,
                                                 "timeout": "3000"}):
                pass
        except Exception:
            pass
        charon.stop()
        aka.stop()
        tunnel.destroy()
        write_state(state_path, None)
        write_pcscf(pcscf_path, None)
        for path in (conf, vici_socket):
            if os.path.exists(path):
                os.unlink(path)
        if log_file:
            log_file.flush()


if __name__ == "__main__":
    main()
